import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir, rename, rm, stat } from 'node:fs/promises';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as nozzleInternals from '../models/nozzle-internals.mjs';
import * as fuelFiller from '../models/fuel-filler.mjs';

/*
 * Original models generated by Hold Up code (tools/models/), fed to the same converter, review and registration as
 * downloaded assets. Used only for components that cannot reasonably be sourced. Provenance points at the generator
 * source; the geometry is dedicated CC0. Output is cached by generator version + parameters.
 */
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const REPO = 'https://github.com/Evan-Wheeler3/chatgpt-clips/blob/main';
export const GENERATORS = {
  'nozzle-internals':{module:nozzleInternals, source:'tools/models/nozzle-internals.mjs', write:nozzleInternals.writeMechanismGlb,
    name:'Automatic fuel nozzle shut-off mechanism (internals)', description:'Main valve poppet, seat and spring, venturi and suction port, diaphragm chamber and diaphragm, latch pin, balls and plunger with the lever pivot, sensing tube and tip hole; named animatable parts',
    tags:['nozzle', 'mechanism', 'cutaway', 'fuel', 'internals'], style:'stylized'},
  'fuel-filler':{module:fuelFiller, source:'tools/models/fuel-filler.mjs', write:fuelFiller.writeFillerGlb,
    name:'Car fuel-filler assembly', description:'Bezel, recessed pocket, hollow filler neck angled into the car with a dark opening, open fuel door; mount and neck sockets',
    tags:['fuel', 'filler', 'door', 'neck', 'opening'], style:'stylized'}
};
const sha256 = data => createHash('sha256').update(data).digest('hex');

export function createGeneratedProvider({cacheDir = resolve(root, 'assets/cache'), params = {}} = {}) {
  async function fetchModel(id) {
    const g = GENERATORS[id];
    if (!g) throw new Error(`No generator "${id}" (${Object.keys(GENERATORS).join(', ')})`);
    const version = sha256(JSON.stringify({v:g.module.VERSION, source:sha256(await readFile(join(root, g.source))), params})).slice(0, 12);
    const dest = join(cacheDir, 'generated', id, version);
    try {
      const provenance = JSON.parse(await readFile(join(dest, 'provenance.json'), 'utf8'));
      const data = await readFile(join(dest, provenance.entry));
      if (sha256(data) === provenance.files[0].sha256) return {status:'cached', dir:dest, provenance};
    } catch { /* Generate below */ }
    const partial = `${dest}.partial-${process.pid}`;
    await rm(partial, {recursive:true, force:true}); await mkdir(partial, {recursive:true});
    try {
      const built = await g.write(join(partial, 'model.gltf'), params);
      const files = [];
      for (const path of ['model.gltf', 'model.bin']) { const data = await readFile(join(partial, path)); files.push({path, size:data.length, sha256:sha256(data)}); }
      const provenance = {version:1, provider:'generated', id, name:g.name, generator:g.source, generatorVersion:g.module.VERSION, modelVersion:version, params:built.params, parts:built.parts,
        sourceUrl:`${REPO}/${g.source}`, license:'CC0-1.0', licenseEvidence:`Original geometry generated by ${g.source} (Hold Up); dedicated to the public domain under CC0 1.0`,
        creator:'Hold Up (generated)', entry:'model.gltf', files};
      await writeFile(join(partial, 'provenance.json'), JSON.stringify(provenance, null, 2) + '\n');
      await mkdir(dirname(dest), {recursive:true});
      await rm(dest, {recursive:true, force:true});
      await rename(partial, dest);
      return {status:'generated', dir:dest, provenance};
    } catch (err) { await rm(partial, {recursive:true, force:true}); throw err; }
  }

  async function conversionSource(id) {
    const fetched = await fetchModel(id), p = fetched.provenance, g = GENERATORS[id];
    return {provider:'generated', id, version:p.modelVersion, dir:fetched.dir, entry:p.entry, fetchStatus:fetched.status, files:p.files,
      attribution:{name:p.name, sourceUrl:p.sourceUrl, license:p.license, licenseEvidence:p.licenseEvidence, creator:p.creator},
      metadata:{name:p.name, description:g.description, tags:g.tags, category:'Mechanism', style:g.style, warnings:[]}, expected:null};
  }
  return {name:'generated', search:async () => [], fetchModel, conversionSource};
}
